<?php $oldInput=App\Core\Session::get('_old');$hasOld=is_array($oldInput);$value=static fn(string$key,mixed$default='')=>old($key,$plan[$key]??$default);$oldFeatures=$hasOld?($oldInput['features']??[]):$plan['features'];$oldLimits=$hasOld?($oldInput['limits']??[]):$plan['limits'];$isPublic=$hasOld?isset($oldInput['is_public']):(bool)$plan['is_public'];$isActive=$hasOld?isset($oldInput['is_active']):(bool)$plan['is_active']; ?>
<section><div class="page-heading"><div><a class="back-link" href="/sa/plans">← Plans</a><p class="eyebrow">Plan configuration</p><h1><?= e($plan['name']) ?></h1><p class="muted">Code <code><?= e($plan['code']) ?></code> is immutable. Unknown future configuration keys are preserved.</p></div></div><form method="post" action="/sa/plans/<?= e($plan['id']) ?>" class="admin-plan-editor"><?= csrf_field() ?><section class="panel form-section"><div class="section-heading"><span>01</span><div><h2>Commercial details</h2><p>Displayed to merchants and used for configured MRR.</p></div></div><div class="form-grid compact-grid"><label>Name<input name="name" value="<?= e($value('name')) ?>" maxlength="80" required></label><label>Monthly price<input name="monthly_price" value="<?= e($value('monthly_price')) ?>" inputmode="decimal" <?= $plan['code']==='FREE'?'readonly':'' ?> required></label><label>Currency<select name="currency_code"><?php foreach(config('app')['currencies']as$currency):?><option value="<?= e($currency) ?>" <?= $value('currency_code')===$currency?'selected':'' ?>><?= e($currency) ?></option><?php endforeach ?></select></label><label>Sort order<input type="number" name="sort_order" value="<?= e($value('sort_order',0)) ?>" min="0" max="10000"></label><label class="full">Description<textarea name="description" maxlength="255" rows="3"><?= e($value('description')) ?></textarea></label><label class="check-row"><input type="checkbox" name="is_public" value="1" <?= $isPublic?'checked':'' ?> <?= $plan['code']==='FREE'?'disabled':'' ?>><span>Visible to merchants</span></label><label class="check-row"><input type="checkbox" name="is_active" value="1" <?= $isActive?'checked':'' ?> <?= $plan['code']==='FREE'?'disabled':'' ?>><span>Available for assignment</span></label><?php if($plan['code']==='FREE'):?><input type="hidden" name="is_public" value="1"><input type="hidden" name="is_active" value="1"><?php endif ?></div></section><section class="panel form-section"><div class="section-heading"><span>02</span><div><h2>Resource limits</h2><p>Use -1 for unlimited. Downgrades preserve existing merchant data.</p></div></div><div class="form-grid compact-grid"><?php foreach($definitions['limits']as$key=>$definition):?><label><?= e($definition['label']) ?><input type="number" name="limits[<?= e($key) ?>]" value="<?= e($oldLimits[$key]??0) ?>" min="-1" max="<?= e($definition['max']) ?>" required></label><?php endforeach ?></div></section><section class="panel form-section"><div class="section-heading"><span>03</span><div><h2>Feature entitlements</h2><p>These values are checked on the server, not only hidden in the interface.</p></div></div><div class="admin-feature-grid"><?php foreach($definitions['features']as$key=>$label):?><label class="check-row"><input type="checkbox" name="features[<?= e($key) ?>]" value="1" <?= !empty($oldFeatures[$key])?'checked':'' ?> <?= $plan['code']==='FREE'&&$key==='basic_storefront'?'disabled':'' ?>><span><?= e($label) ?></span></label><?php endforeach ?><?php if($plan['code']==='FREE'):?><input type="hidden" name="features[basic_storefront]" value="1"><?php endif ?></div></section><div class="design-save"><span>Changes affect entitlement checks immediately. Existing catalog and order records are never deleted.</span><button class="button primary" type="submit">Save plan configuration</button></div></form></section>
